import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Extract scene position data
  const scenePos = config.scenePosition || {};
  const rotXYZ = scenePos.rotationXYZ || [0, 0, 0];
  const scaleXYZ = scenePos.scaleXYZ || [1, 1, 1];
  const posX = scenePos.x || 0;
  const posY = scenePos.y || 0;
  const posZ = scenePos.z || 0;

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load image texture via cached loader
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/feature-card.png';
  const texture = ctx.textureLoader.load(imageUrl);

  // Create material for the plane
  const material = new THREE.MeshBasicMaterial();
  material.map = texture;

  // Create and position the plane mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(posX, posY, posZ);
  mesh.rotation.set(rotXYZ[0], rotXYZ[1], rotXYZ[2]);
  mesh.scale.set(scaleXYZ[0], scaleXYZ[1], scaleXYZ[2]);

  group.add(mesh);

  // Render text content via MSDF font atlas
  if (ctx.fontAtlas) {
    const textMesh = ctx.fontAtlas.createTextMesh({
      text: 'Collection',
      font: 'Lora',
      size: 0.34,
      weight: 400,
      color: 0x16161d,
      align: 'center'
    });

    if (textMesh) {
      textMesh.position.z = posZ + 0.05;
      group.add(textMesh);
    }
  }

  // Apply cinematic primitives
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(function(primitive) {
      if (ctx.primitives && typeof ctx.primitives[primitive.name] === 'function') {
        ctx.primitives[primitive.name](group, primitive.params || {});
      }
    });
  }

  // Cleanup function for resource disposal
  group.userData.cleanup = function() {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    gsap.killTweensOf(group);
  };

  // Event handlers
  group.userData.handlers = {
    onPointerOver: function() {},
    onClick: function() {},
    onPointerOut: function() {}
  };

  return group;
}
